exercises.solution:
class BankAccount:
    def __init__(self, start=0):
        self.bal = start

    def deposit(self, amount):
        self.bal += amount

    def withdraw(self, amount):
        if amount > self.bal:
            raise ValueError('insufficient funds')
        self.bal -= amount

    def balance(self):
        return self.bal

